import { celsius2fahrenheit } from '../Math';
export const hexToRGBANormalized = (hex: string, visibility: number = 1, isGray: boolean = false) => {
    hex = hex.replace('#', '');
    const r = parseInt(hex.substring(0, 2), 16);
    const g = parseInt(hex.substring(2, 4), 16);
    const b = parseInt(hex.substring(4, 6), 16);
    if (isGray) {
        // let v = (0.58 * (r / 255)) + (0.17 * (g / 255)) + (0.8 * (b / 255));
        let v = (0.58 * r) + (0.17 * g) + (0.8 * b);
        return [v, v, v, visibility];
    } else {
        return [r / 255, g / 255, b / 255, visibility / 255];
    }
};
export const hex2RGBA = (hex: string, visibility: number = 1, isGray: boolean = false) => {
    hex = hex.replace('#', '');
    let r = parseInt(hex.substring(0, 2), 16);
    let g = parseInt(hex.substring(2, 4), 16);
    let b = parseInt(hex.substring(4, 6), 16);
    if (isGray) {
        // let v = (0.58 * (r / 255)) + (0.17 * (g / 255)) + (0.8 * (b / 255));
        let v = (0.58 * r) + (0.17 * g) + (0.8 * b);
        return [v, v, v, visibility];
    } else {
        return [r, g, b, visibility];
    }
}
/**
 * 
 * @param c Celsius
 * @returns [r, g, b] 0 - 255
 */
 export const getColorByCelsius = (c: number) => {
    return getColorByFahrenheit(celsius2fahrenheit(c));
 }
/**
 * 
 * @param v Fahrenheit
 * @returns [r, g, b] 0 - 255
 */
 const getColorByFahrenheit = (v: number) => { // 38 degree
    if (120 < v  && v <= 150 ) {
        return [62, 2, 22]
    } else if (115 < v  && v <= 120 ) {
        return [85, 12, 37]
    } else if (110 < v  && v <= 115 ) {
        return [110, 21, 49]
    } else if (105 < v  && v <= 110 ) {
        return [115, 32, 62]
    } else if (100 < v  && v <= 105 ) {
        return [159, 41, 76]
    } else if (95 < v  && v <= 100 ) {
        return [175, 77, 78]
    } else if (90 < v  && v <= 95 ) {
        return [190, 112, 76]
    } else if (85 < v  && v <= 90 ) {
        return [195, 138, 83]
    } else if (80 < v  && v <= 85 ) {
        return [193, 157, 97]
    } else if (75 < v  && v <= 80 ) {
        return [194, 171, 117]
    } else if (70 < v  && v <= 75 ) {
        return [171, 168, 125]
    } else if (65 < v  && v <= 70 ) {
        return [135, 154, 132]
    } else if (60 < v  && v <= 65 ) {
        return [100, 141, 137]
    } else if (55 < v  && v <= 60 ) {
        return [67, 129, 144]
    } else if (50 < v  && v <= 55 ) {
        return [40, 117, 147]
    } else if (45 < v  && v <= 50 ) {
        return [39, 103, 138]
    } else if (40 < v  && v <= 45 ) {
        return [39, 91, 128]
    } else if (35 < v  && v <= 40 ) {
        return [37, 79, 119]
    } else if (30 < v  && v <= 35 ) {
        return [38, 67, 111]
    } else if (25 < v  && v <= 30 ) {
        return [47, 71, 117]
    } else if (20 < v  && v <= 25 ) {
        return [57, 81, 127]
    } else if (15 < v  && v <= 20 ) {
        return [65, 92, 135]
    } else if (10 < v  && v <= 15 ) {
        return [77, 101, 145]
    } else if (5 < v  && v <= 10 ) {
        return [86, 113, 156]
    } else if (0 < v  && v <= 5 ) {
        return [98, 123, 166]
    } else if (-5 < v  && v <= 0 ) {
        return [117, 145, 185]
    } else if (-10 < v  && v <= -5 ) {
        return [128, 155, 192]
    } else if (-15 < v  && v <= -10 ) {
        return [138, 164, 205]
    } else if (-20 < v  && v <= -15 ) {
        return [147, 177, 215]
    } else if (-25 < v  && v <= -20 ) {
        return [156, 184, 223]
    } else if (-30 < v  && v <= -25 ) {
        return [167, 191, 227]
    } else if (-35 < v  && v <= -30 ) {
        return [175, 198, 231]
    } else if (-40 < v  && v <= -35 ) {
        return [184, 205, 234]
    } else if (-45 < v  && v <= -40 ) {
        return [192, 212, 237]
    } else if (-50 < v  && v <= -45 ) {
        return [203, 219, 244]
    } else if (-55 < v  && v <= -50 ) {
        return [211, 226, 247]
    } else if (-60 < v  && v <= -55 ) {
        return [220, 233, 250]
    } else if (-100 < v  && v <= -60 ) {
        return [228, 240, 255]
    } else {
        return [0, 0, 0]
    }
}
export const RGBToHex = (r: number, g: number, b: number) => {
    return '#' + [Math.round(r), Math.round(g), Math.round(b)].map(x => {
        const hex = x.toString(16);
        return hex.length === 1 ? '0' + hex : hex;
    }).join('');
}
/**
 * 
 * @returns string
 */
export const getRandomHex = () => {
    return RGBToHex(Math.round(Math.random() * 255), Math.round(Math.random() * 255), Math.round(Math.random() * 255));
}
/**
 * 
 * @returns [r, g, b] the string values between 0 to 255 
 */
 export const getRandomRGBString = () => {
    return `rgb(${Math.round(Math.random() * 255)},${Math.round(Math.random() * 255)},${Math.round(Math.random() * 255)})`;
}
/**
 * 
 * @returns [r, g, b, a] the string values between 0 to 255 
 */
 export const getRandomRGBAString = () => {
    return `rgb(${Math.round(Math.random() * 255)},${Math.round(Math.random() * 255)},${Math.round(Math.random() * 255)},1)`;
}
/**
 * 
 * @returns [r, g, b] the normalized value array between 0 to 255 
 */
 export const getRandomRGBArray = () => {
    return [(Math.round(Math.random() * 255)), (Math.round(Math.random() * 255)), (Math.round(Math.random() * 255))];
}
/**
 * 
 * @param r 0 - 1
 * @param g 0 - 1
 * @param b 0 - 1
 * @returns 
 */
 export const RGBtoGray = (r: number, g: number, b: number) => {
    return 0.2126 * r + 0.7152 * g + 0.0722 * b;
}
/**
 * 
 * @param value 0 - 1
 * @returns [r, g, b]
 */
export const getFalseColor = (value: number): number[] => {
    const col: number[] = [];
    col.push(Math.round(getR(value) * 255));
    col.push(Math.round(getG(value) * 255));
    col.push(Math.round(getB(value) * 255));
    return col;
};
const getR = (value: number, min = 0, max = 1) => {
    value = (value - min) / (max - min);
    if (value <= 0.25)
        return 0;
    else if (value <= 0.5)
        return (1020. * value - 255.) / 255.;
    else return 1;
};
const getB = (value: number, min = 0, max = 1) => {
    value = (value - min) / (max - min);
    if (value <= 0.25)
        return (-512 * value + 128) / 255;
    else return 0;
};
const getG = (value: number, min = 0, max = 1) => {
    value = (value - min) / (max - min);
    if (value <= 0.25)
        return (1020 * value) / 255;
    else if (value <= 0.5)
        return 1;
    else
        return (-510 * value + 510) / 255;
};
/**
 * r g b a are the normalized values between 0 to 1 
 */
export class Color {
    public r: number = 0;
    public g: number = 0;
    public b: number = 0;
    public a: number = 1;
    constructor(r: number, g: number, b: number, a: number = 1) {
        this.r = r;
        this.g = g;
        this.b = b;
        this.a = a;
    }
}

